// Plan-generation cluster — Phase 3 slice 5 re-scope (3c).
//
// The auto-generated-plan subsystem lifted out of loop-controller.js: plan
// task submission/reuse/lookup, provider-fallback + retry result builders,
// terminal-markdown recovery, validation-command routing, auto-generated-plan
// markdown normalization + task shaping, the plan reviewer + linter, and
// plan-path migration. 71 functions across 18 source zones (25 referenced by
// loop-controller's PLAN/EXECUTE block, 46 cluster-internal fold-ins from
// fixed-point boundary analysis). createPlanGenerationCluster(deps) injects
// 21 loop-controller helpers; 13 plan-generation constants moved in as module
// constants; leaf modules required directly. loop-controller keeps an early
// one-line wiring and re-imports PLAN_GENERATOR_LABEL / WORK_ITEM_STATUS_ORDER.

const fs = require('fs');
const path = require('path');
const logger = require('../logger').child({ component: 'factory-plan-generation' });
const architectRunner = require('../factory/architect-runner');
const factoryIntake = require('../db/factory/intake');
const factoryWorktrees = require('../db/factory/worktrees');
const { LOOP_STATES } = require('./loop-states');
const { DEFAULT_STALE_PENDING_PLAN_GENERATION_MS, clearPlanGenerationWaitFields } = require('./plan-generation/timeout-policy');
const { buildAutoGeneratedPlanPath, extractPlanDescriptionFilePaths, inferAutoGeneratedPlanTechStack, normalizePlanProjectRelativePath, projectFileExists } = require('./shared/plan-path');
const { buildImplementationTaskTitle, buildTaskValidationDetail, formatPlanDescriptionFileList, getTaskSpecificityFilePaths } = require('./plan-builders/task-spec');
const { buildPlanDescriptionQualityRejectPayload } = require('./plan-builders/quality-reject');
const { buildPlanFromFileEditsProposal, buildPlanFromNumberedTaskSummary, convertFencedBlocksToIndented, trimPromptEchoTail, unwrapWholeMarkdownFence } = require('./plan-builders/from-output');
const { buildWorkItemSuccessDetail } = require('./plan-builders/workitem-spec');
const { buildProviderLaneTaskMetadata } = require('./provider-lane-policy');
const { chooseRelatedReplacementFile, collectArchitectScopeDetails, collectArchitectScopeFiles, discoverExistingFileAlternates, discoverRelatedProjectFiles, escapeRegExpLiteral, findUniqueProjectFileByBasename, isPlanTestPath } = require('./shared/scope-search');
const { createPlanReviewer, selectReviewers } = require('./plan-reviewer');
const { findHeavyLocalValidationCommand } = require('../utils/heavy-validation-guard');
const { getWorkItemConstraintsObject, getWorkItemOriginObject } = require('./shared/workitem-accessors');

const PLAN_GENERATOR_LABEL = 'auto-router';
const WORK_ITEM_STATUS_ORDER = Object.freeze([
  'executing',
  'verifying',
  'planned',
  'prioritized',
  'in_progress',
  'pending',
  'triaged',
  'intake',
  // Phase X1 (2026-05-01): items whose current plan failed quality/parse/
  // timeout/empty-diff checks. Placed last so fresh `pending` items get
  // first dibs; needs_replan items only get picked when no fresh work
  // exists. Cooldown filter (NEEDS_REPLAN_COOLDOWN_MS) further prevents
  // immediate re-loop after a rejection.
  'needs_replan',
]);
const PLAN_GENERATION_PROVIDER_FALLBACK_LIMIT = 1;
const PLAN_GENERATION_PROVIDER_FALLBACK_PROVIDER = 'claude-cli';
const TRANSIENT_PLAN_GENERATION_PROVIDER_ERROR_RE =
  /\b(?:ETIMEDOUT|ECONNRESET|ECONNREFUSED|EHOSTUNREACH|ENETUNREACH|UND_ERR_CONNECT_TIMEOUT)\b|connect\s+\S*\s*timed?\s*out|socket hang up|fetch failed/i;
const ACTIVE_PLAN_GENERATION_TASK_STATUSES = Object.freeze([
  'pending',
  'pending_approval',
  'pending_provider_switch',
  'queued',
  'retry_scheduled',
  'running',
  'waiting',
  'blocked',
]);
const VALIDATION_TARGET_PATH_RE = /\b[A-Za-z0-9_.][A-Za-z0-9_./\\-]*\.(?:csproj|fsproj|vbproj|targets|props|cjs|cs|css|go|html|java|js|json|jsx|md|mjs|psm1|ps1|py|rb|resx|rs|sh|sln|sql|ts|tsx|txt|xaml|axaml|xml|ya?ml)\b/gi;
const VALIDATION_COMMAND_LINE_RE = /\b(?:npx\s+vitest(?:\s+run)?|vitest(?:\s+run)?|pytest|python\s+-m\s+pytest|npm(?:\s+--prefix\s+\S+)?\s+(?:run\s+)?test\s+--)\b/i;
const PLAN_GENERATION_IMPLEMENTATION_SIGNAL_RE = /\b(?:add|create|define|expose|export|extract|fix|harden|implement|introduce|persist|refactor|repair|support|test|validate|wire)\b/i;
const PLAN_GENERATION_INVESTIGATION_TITLE_RE = /^\s*(?:audit|diagnose|explore|investigate|review|trace)\b/i;
const PLAN_GENERATION_ANALYSIS_TASK_TITLE_RE = /^\s*(?:identify|analy[sz]e|locate|inspect|examine|research|investigate|review|read|search|find)\b/i;
const PLAN_GENERATION_CHANGE_STEP_RE = /\b(?:add|create|define|edit|expose|export|extract|implement|introduce|modify|persist|replace|rewrite|test|validate|wire)\b/i;
const PLAN_QUALITY_SOFT_THRESHOLD = 5;

const PLAN_GENERATION_FN_DEPS = [
  'augmentAutoGeneratedTaskSpecificity',
  'extractCodexFinalAnswerFromTranscript',
  'extractTextContent',
  'getDecisionBatchId',
  'getDefaultFactoryBatchId',
  'getTaskMetadataObject',
  'getWorkItemDecisionContext',
  'getWorktreeRunner',
  'hasObjectLevelDetail',
  'isAutoGeneratedPlanPath',
  'isSchedulerOwnedPlanGenerationTask',
  'isStaleNeverStartedPendingPlanGenerationTask',
  'looksLikeDirectPlanMarkdown',
  'normalizeOptionalString',
  'normalizeTaskTags',
  'normalizeWorkItemId',
  'nowIso',
  'parseJsonObject',
  'rememberSelectedWorkItem',
  'safeLogDecision',
  'scoreAutoGeneratedPlanDescriptions',
  'ensureReusedFactoryWorktreeFresh',
  'factoryWorktreeBelongsToWorkItem',
  'getFactoryWorktreePath',
  'getFactoryWorktreeWorkItemId',
  'prepareReusedFactoryWorktreeDependencies',
];

function createPlanGenerationCluster(deps = {}) {
  for (const name of PLAN_GENERATION_FN_DEPS) {
    if (typeof deps[name] !== 'function') {
      throw new TypeError(`createPlanGenerationCluster: dep '${name}' is required`);
    }
  }
  const {
    augmentAutoGeneratedTaskSpecificity,
    extractCodexFinalAnswerFromTranscript,
    extractTextContent,
    getDecisionBatchId,
    getDefaultFactoryBatchId,
    getTaskMetadataObject,
    getWorkItemDecisionContext,
    getWorktreeRunner,
    hasObjectLevelDetail,
    isAutoGeneratedPlanPath,
    isSchedulerOwnedPlanGenerationTask,
    isStaleNeverStartedPendingPlanGenerationTask,
    looksLikeDirectPlanMarkdown,
    normalizeOptionalString,
    normalizeTaskTags,
    normalizeWorkItemId,
    nowIso,
    parseJsonObject,
    rememberSelectedWorkItem,
    safeLogDecision,
    scoreAutoGeneratedPlanDescriptions,
    ensureReusedFactoryWorktreeFresh,
    factoryWorktreeBelongsToWorkItem,
    getFactoryWorktreePath,
    getFactoryWorktreeWorkItemId,
    prepareReusedFactoryWorktreeDependencies,
  } = deps;

  function retireStalePendingPlanGenerationTask(taskCore, task, {
    projectId = null,
    workItemId = null,
    staleAfterMs = DEFAULT_STALE_PENDING_PLAN_GENERATION_MS,
    reason = 'stale_pending_plan_generation',
    requireSchedulerOwned = false,
  } = {}) {
    if (!isStaleNeverStartedPendingPlanGenerationTask(task, staleAfterMs, {
      projectId,
      workItemId,
      requireSchedulerOwned,
    })) {
      return false;
    }
    if (!taskCore || typeof taskCore.updateTaskStatus !== 'function' || !task?.id) {
      return false;
    }

    try {
      taskCore.updateTaskStatus(task.id, 'skipped', {
        output: 'Superseded stale never-started plan-generation task.',
        error_output: `Skipped stale never-started plan-generation task: ${reason}`,
      });
      logger.warn('Retired stale pending plan-generation task', {
        project_id: projectId,
        work_item_id: workItemId,
        task_id: task.id,
        status: task.status,
        created_at: task.created_at || task.createdAt || null,
        reason,
      });
      return true;
    } catch (error) {
      logger.warn('Failed to retire stale pending plan-generation task', {
        project_id: projectId,
        work_item_id: workItemId,
        task_id: task.id,
        err: error.message,
        reason,
      });
      return false;
    }
  }

  async function abandonReusedFactoryWorktreeAfterFreshnessFailure({
    worktreeRunner,
    worktreeRecord,
    reason,
  }) {
    if (!worktreeRecord?.id) {
      return;
    }
    factoryWorktrees.markAbandoned(worktreeRecord.id, reason);
    if (typeof worktreeRunner?.abandon === 'function' && worktreeRecord.vcWorktreeId) {
      await worktreeRunner.abandon({
        id: worktreeRecord.vcWorktreeId,
        branch: worktreeRecord.branch,
        reason,
      });
    }
  }

  function getFactorySubmissionBatchId(project, workItem, instance = null) {
    return getDecisionBatchId(project, workItem, null, instance)
      || getDefaultFactoryBatchId(project, workItem);
  }

  function getStoredPlanGeneratorProvider(workItem) {
    const direct = normalizeOptionalString(workItem?.origin?.plan_generator_provider);
    if (direct) {
      return direct;
    }
    const parsedOrigin = parseJsonObject(workItem?.origin_json);
    return normalizeOptionalString(parsedOrigin?.plan_generator_provider);
  }

  function getStoredPlanGenerationTaskId(workItem) {
    const direct = normalizeOptionalString(workItem?.origin?.plan_generation_task_id);
    if (direct) {
      return direct;
    }
    const parsedOrigin = parseJsonObject(workItem?.origin_json);
    return normalizeOptionalString(parsedOrigin?.plan_generation_task_id);
  }

  function isStalePlanGenerationFileLockWait(task, nowMs = Date.now()) {
    const metadata = getTaskMetadataObject(task);
    const wait = metadata.file_lock_wait;
    if (!wait || typeof wait !== 'object' || Array.isArray(wait)) {
      return false;
    }

    const status = String(task?.status || '').toLowerCase();
    if (status === 'running') {
      return true;
    }

    const retryAfter = normalizeOptionalString(wait.retry_after);
    if (!retryAfter) {
      return false;
    }

    const retryAfterMs = Date.parse(retryAfter);
    return Number.isFinite(retryAfterMs) && retryAfterMs <= nowMs;
  }

  function getPlanGenerationFileLockWait(task, message = '') {
    if (isStalePlanGenerationFileLockWait(task)) {
      return null;
    }

    const metadata = getTaskMetadataObject(task);
    const wait = metadata.file_lock_wait;
    if (wait && typeof wait === 'object' && !Array.isArray(wait)) {
      return { ...wait, reason: 'file_lock_wait' };
    }

    const text = [
      message,
      typeof task?.error_output === 'string' ? task.error_output : '',
    ].filter(Boolean).join('\n');
    if (/Requeued:\s*file\s+'[^']+'\s+is being edited by task\b/i.test(text)) {
      return { reason: 'file_lock_wait' };
    }
    return null;
  }

  function getPlanGenerationRunningWait(task, message = '') {
    if (!isPlanGenerationTaskPending(task)) {
      return null;
    }

    const text = [
      message,
      typeof task?.error_output === 'string' ? task.error_output : '',
    ].filter(Boolean).join('\n');

    if (!text || /task\s+timed\s+out|timed\s+out|timeout|status:\s*(?:running|queued|pending|waiting)\b/i.test(text)) {
      return { reason: 'task_still_running' };
    }
    return null;
  }

  function getPlanGenerationWait(task, message = '') {
    if (isPlanGenerationTaskPending(task) && isStalePlanGenerationFileLockWait(task)) {
      return { reason: 'task_still_running' };
    }

    return getPlanGenerationFileLockWait(task, message)
      || getPlanGenerationRunningWait(task, message);
  }

  function isPlanGenerationTaskPending(task) {
    return ['pending', 'queued', 'running', 'waiting'].includes(
      String(task?.status || '').toLowerCase()
    );
  }

  function getPlanGenerationTask(taskCore, taskId) {
    if (!taskCore || typeof taskCore.getTask !== 'function' || !taskId) {
      return null;
    }
    try {
      return taskCore.getTask(taskId) || null;
    } catch (error) {
      logger.debug('Unable to load plan-generation task state', {
        task_id: taskId,
        err: error.message,
      });
      return null;
    }
  }

  function persistPlanGenerationTaskReplacement(workItem, generationTaskId) {
    if (!workItem?.id || !generationTaskId) {
      return workItem;
    }
    const origin = getWorkItemOriginObject(workItem);
    if (origin.plan_generation_task_id === generationTaskId) {
      return workItem;
    }
    try {
      return factoryIntake.updateWorkItem(workItem.id, {
        origin_json: {
          ...origin,
          plan_generation_task_id: generationTaskId,
          plan_generation_updated_at: nowIso(),
        },
      });
    } catch (error) {
      logger.warn('EXECUTE stage: failed to persist plan-generation replacement task id', {
        work_item_id: workItem.id,
        generation_task_id: generationTaskId,
        err: error.message,
      });
      return workItem;
    }
  }

  function buildPlanGenerationDeferredResult({
    project,
    instance,
    targetItem,
    planPath,
    generationTaskId,
    generationTask,
    wait,
    reason,
  }) {
    const status = generationTask?.status || 'queued';
    const waitReason = normalizeOptionalString(wait?.reason) || 'task_still_running';
    const isFileLockWait = waitReason === 'file_lock_wait';
    const retryAfter = normalizeOptionalString(wait?.retry_after);
    const deferredOrigin = {
      ...getWorkItemOriginObject(targetItem),
      plan_path: planPath,
      plan_generation_task_id: generationTaskId,
      plan_generation_status: status,
      plan_generation_wait_reason: waitReason,
      ...(retryAfter ? { plan_generation_retry_after: retryAfter } : {}),
      plan_generation_updated_at: nowIso(),
    };
    let updatedWorkItem = targetItem;
    try {
      updatedWorkItem = factoryIntake.updateWorkItem(targetItem.id, {
        origin_json: deferredOrigin,
        status: targetItem.status || 'planned',
      });
      rememberSelectedWorkItem(instance.id, updatedWorkItem);
    } catch (error) {
      logger.warn('EXECUTE stage: failed to persist deferred plan-generation state', {
        project_id: project.id,
        work_item_id: targetItem.id,
        generation_task_id: generationTaskId,
        err: error.message,
      });
    }

    logger.info(isFileLockWait
      ? 'EXECUTE stage: deferred plan generation for file-lock contention'
      : 'EXECUTE stage: deferred plan generation while task remains active', {
      project_id: project.id,
      work_item_id: targetItem.id,
      plan_path: planPath,
      generation_task_id: generationTaskId,
      reason: waitReason,
      task_status: status,
      retry_after: retryAfter || null,
    });
    safeLogDecision({
      project_id: project.id,
      stage: LOOP_STATES.EXECUTE,
      action: isFileLockWait ? 'plan_generation_deferred_file_lock' : 'plan_generation_deferred_running',
      reasoning: reason || (isFileLockWait
        ? 'plan generation task is waiting on file-lock contention'
        : 'plan generation task is still active'),
      inputs: {
        ...getWorkItemDecisionContext(targetItem),
      },
      outcome: {
        reason: waitReason,
        plan_path: planPath,
        generation_task_id: generationTaskId,
        task_status: status,
        retry_after: retryAfter || null,
        ...getWorkItemDecisionContext(targetItem),
      },
      confidence: 1,
      batch_id: getDecisionBatchId(project, updatedWorkItem, null, instance),
    });

    return {
      reason: isFileLockWait
        ? 'plan generation deferred for file-lock contention'
        : 'plan generation deferred while task remains active',
      work_item: updatedWorkItem,
      stop_execution: true,
      next_state: LOOP_STATES.EXECUTE,
      paused_at_stage: LOOP_STATES.EXECUTE,
      stage_result: {
        status: 'deferred',
        reason: waitReason,
        plan_path: planPath,
        generation_task_id: generationTaskId,
        task_status: status,
        retry_after: retryAfter || null,
      },
    };
  }

  function getPlanGenerationRetryCount(workItem) {
    const origin = getWorkItemOriginObject(workItem);
    const count = Number(origin.plan_generation_retry_count || 0);
    return Number.isFinite(count) && count > 0 ? Math.floor(count) : 0;
  }

  function getPlanGenerationProviderFallbackCount(workItem) {
    const origin = getWorkItemOriginObject(workItem);
    const count = Number(origin.plan_generation_provider_fallback_count || 0);
    return Number.isFinite(count) && count > 0 ? Math.floor(count) : 0;
  }

  function isTransientPlanGenerationProviderError(error) {
    const text = [
      error && typeof error.message === 'string' ? error.message : '',
      error && typeof error.code === 'string' ? error.code : '',
      typeof error === 'string' ? error : '',
    ].filter(Boolean).join('\n');
    return TRANSIENT_PLAN_GENERATION_PROVIDER_ERROR_RE.test(text);
  }

  async function buildPlanGenerationProviderFallbackResult({
    project,
    instance,
    targetItem,
    planPath,
    generationTaskId,
    generationTask,
    error,
    submitFactoryInternalTask,
    prompt,
    planGenerationWorkingDirectory,
    planGenerationFiles,
    planGenerationTimeoutMinutes,
    planGenerationActivityTimeoutPolicy,
  }) {
    if (!isTransientPlanGenerationProviderError(error)) {
      return null;
    }

    const fallbackCount = getPlanGenerationProviderFallbackCount(targetItem);
    if (fallbackCount >= PLAN_GENERATION_PROVIDER_FALLBACK_LIMIT) {
      return null;
    }

    const origin = getWorkItemOriginObject(targetItem);
    const failedProvider = normalizeOptionalString(generationTask?.provider)
      || normalizeOptionalString(origin.plan_generator_provider)
      || PLAN_GENERATOR_LABEL;
    if (failedProvider === PLAN_GENERATION_PROVIDER_FALLBACK_PROVIDER) {
      return null;
    }

    let fallbackTaskId = null;
    try {
      const submitted = await submitFactoryInternalTask({
        task: prompt,
        provider: PLAN_GENERATION_PROVIDER_FALLBACK_PROVIDER,
        working_directory: planGenerationWorkingDirectory,
        kind: 'plan_generation',
        project_id: project.id,
        work_item_id: targetItem.id,
        files: planGenerationFiles.length > 0 ? planGenerationFiles : undefined,
        context_stuff: false,
        study_context: false,
        timeout_minutes: planGenerationTimeoutMinutes,
        extra_metadata: {
          activity_timeout_policy: planGenerationActivityTimeoutPolicy,
          plan_generation_provider_fallback: true,
          plan_generation_failed_provider: failedProvider,
          plan_generation_failed_task_id: generationTaskId || null,
        },
      });
      fallbackTaskId = submitted?.task_id || null;
    } catch (fallbackErr) {
      logger.warn('EXECUTE stage: plan-generation provider fallback submit failed', {
        project_id: project.id,
        work_item_id: targetItem.id,
        failed_generation_task_id: generationTaskId || null,
        failed_provider: failedProvider,
        fallback_provider: PLAN_GENERATION_PROVIDER_FALLBACK_PROVIDER,
        err: fallbackErr.message,
      });
      return null;
    }

    if (!fallbackTaskId) {
      return null;
    }

    const fallbackOrigin = {
      ...clearPlanGenerationWaitFields(origin),
      plan_path: planPath,
      plan_generation_task_id: fallbackTaskId,
      plan_generation_status: 'submitted',
      plan_generation_provider_fallback_count: fallbackCount + 1,
      plan_generation_provider_fallback_from: failedProvider,
      plan_generation_provider_fallback_to: PLAN_GENERATION_PROVIDER_FALLBACK_PROVIDER,
      plan_generation_provider_fallback_error: String(error?.message || error || '').slice(0, 1000),
      plan_generation_updated_at: nowIso(),
    };

    let updatedWorkItem = targetItem;
    try {
      updatedWorkItem = factoryIntake.updateWorkItem(targetItem.id, {
        origin_json: fallbackOrigin,
        status: targetItem.status || 'planned',
      });
      rememberSelectedWorkItem(instance.id, updatedWorkItem);
    } catch (persistErr) {
      logger.warn('EXECUTE stage: failed to persist plan-generation provider fallback state', {
        project_id: project.id,
        work_item_id: targetItem.id,
        fallback_task_id: fallbackTaskId,
        err: persistErr.message,
      });
    }

    logger.warn('EXECUTE stage: submitted plan-generation provider fallback after transient provider error', {
      project_id: project.id,
      work_item_id: targetItem.id,
      failed_generation_task_id: generationTaskId || null,
      fallback_generation_task_id: fallbackTaskId,
      failed_provider: failedProvider,
      fallback_provider: PLAN_GENERATION_PROVIDER_FALLBACK_PROVIDER,
      error: String(error?.message || error || '').slice(0, 500),
    });
    safeLogDecision({
      project_id: project.id,
      stage: LOOP_STATES.EXECUTE,
      action: 'plan_generation_provider_fallback_submitted',
      reasoning: `Transient plan-generation provider error from ${failedProvider}; submitted fallback ${PLAN_GENERATION_PROVIDER_FALLBACK_PROVIDER}.`,
      inputs: {
        ...getWorkItemDecisionContext(targetItem),
      },
      outcome: {
        reason: 'transient_provider_error',
        error: String(error?.message || error || '').slice(0, 1000),
        failed_provider: failedProvider,
        fallback_provider: PLAN_GENERATION_PROVIDER_FALLBACK_PROVIDER,
        failed_generation_task_id: generationTaskId || null,
        generation_task_id: fallbackTaskId,
        fallback_count: fallbackCount + 1,
        ...getWorkItemDecisionContext(updatedWorkItem),
      },
      confidence: 0.85,
      batch_id: getDecisionBatchId(project, updatedWorkItem, null, instance),
    });

    return {
      reason: 'plan generation provider fallback submitted after transient provider error',
      work_item: updatedWorkItem,
      stop_execution: true,
      next_state: LOOP_STATES.EXECUTE,
      paused_at_stage: null,
      stage_result: {
        status: 'deferred',
        reason: 'provider_fallback_submitted',
        plan_path: planPath,
        failed_generation_task_id: generationTaskId || null,
        generation_task_id: fallbackTaskId,
        failed_provider: failedProvider,
        fallback_provider: PLAN_GENERATION_PROVIDER_FALLBACK_PROVIDER,
      },
    };
  }

  function buildPlanGenerationRetryResult({
    project,
    instance,
    targetItem,
    planPath,
    generationTaskId,
    error,
  }) {
    const priorRetries = getPlanGenerationRetryCount(targetItem);
    const retryCount = priorRetries + 1;
    const retryAfter = new Date(Date.now() + 60 * 1000).toISOString();
    const origin = getWorkItemOriginObject(targetItem);
    const retryOrigin = {
      ...clearPlanGenerationWaitFields(origin),
      plan_path: planPath,
      plan_generation_status: 'retry_scheduled',
      plan_generation_retry_count: retryCount,
      plan_generation_retry_after: retryAfter,
      plan_generation_last_error: String(error?.message || error || 'unusable plan-generation output').slice(0, 1000),
      plan_generation_updated_at: nowIso(),
    };

    let updatedWorkItem = targetItem;
    try {
      updatedWorkItem = factoryIntake.updateWorkItem(targetItem.id, {
        origin_json: retryOrigin,
        status: targetItem.status || 'planned',
      });
      rememberSelectedWorkItem(instance.id, updatedWorkItem);
    } catch (persistErr) {
      logger.warn('EXECUTE stage: failed to persist plan-generation retry state', {
        project_id: project.id,
        work_item_id: targetItem.id,
        generation_task_id: generationTaskId,
        err: persistErr.message,
      });
    }

    logger.warn('EXECUTE stage: retrying unusable plan-generation output', {
      project_id: project.id,
      work_item_id: targetItem.id,
      generation_task_id: generationTaskId,
      retry_count: retryCount,
      retry_after: retryAfter,
      error: String(error?.message || error || '').slice(0, 500),
    });
    safeLogDecision({
      project_id: project.id,
      stage: LOOP_STATES.EXECUTE,
      action: 'plan_generation_retry_unusable_output',
      reasoning: error?.message || 'plan-generation task completed without executable plan markdown',
      inputs: {
        ...getWorkItemDecisionContext(targetItem),
      },
      outcome: {
        reason: 'unusable_plan_generation_output',
        plan_path: planPath,
        generation_task_id: generationTaskId,
        retry_count: retryCount,
        retry_after: retryAfter,
        ...getWorkItemDecisionContext(targetItem),
      },
      confidence: 0.8,
      batch_id: getDecisionBatchId(project, updatedWorkItem, null, instance),
    });

    return {
      reason: 'plan generation retry scheduled after unusable output',
      work_item: updatedWorkItem,
      stop_execution: true,
      next_state: LOOP_STATES.IDLE,
      stage_result: {
        status: 'retry_scheduled',
        reason: 'unusable_plan_generation_output',
        plan_path: planPath,
        generation_task_id: generationTaskId,
        retry_count: retryCount,
        retry_after: retryAfter,
      },
    };
  }

  function getPlanGeneratorLabel(provider) {
    return normalizeOptionalString(provider) || PLAN_GENERATOR_LABEL;
  }

  function normalizeReusablePlanPath(value) {
    const normalized = normalizeOptionalString(value);
    if (!normalized) return null;
    try {
      return path.resolve(normalized).replace(/\\/g, '/').toLowerCase();
    } catch {
      return normalized.replace(/\\/g, '/').toLowerCase();
    }
  }

  function getReusableTaskMetadata(task) {
    const metadata = task?.metadata ?? task?.task_metadata;
    if (!metadata) return {};
    if (typeof metadata === 'object' && !Array.isArray(metadata)) return metadata;
    if (typeof metadata !== 'string') return {};
    try {
      const parsed = JSON.parse(metadata);
      return parsed && typeof parsed === 'object' && !Array.isArray(parsed) ? parsed : {};
    } catch {
      return {};
    }
  }

  function reusableTaskMatchesPlanContext(candidate, { planPath, workingDirectory }) {
    const expectedPlanPath = normalizeReusablePlanPath(planPath);
    if (!expectedPlanPath) return true;

    const metadata = getReusableTaskMetadata(candidate);
    const candidatePlanPath = normalizeReusablePlanPath(metadata.plan_path || metadata.planPath);
    if (candidatePlanPath) {
      return candidatePlanPath === expectedPlanPath;
    }

    const expectedWorkingDirectory = normalizeReusablePlanPath(workingDirectory);
    const candidateWorkingDirectory = normalizeReusablePlanPath(candidate?.working_directory || candidate?.workingDirectory);
    return Boolean(expectedWorkingDirectory && candidateWorkingDirectory && candidateWorkingDirectory === expectedWorkingDirectory);
  }

  function activeReusableTaskMatchesWorkingDirectory(candidate, workingDirectory) {
    const expectedWorkingDirectory = normalizeReusablePlanPath(workingDirectory);
    const candidateWorkingDirectory = normalizeReusablePlanPath(candidate?.working_directory || candidate?.workingDirectory);
    if (!expectedWorkingDirectory || !candidateWorkingDirectory) {
      return true;
    }
    return candidateWorkingDirectory === expectedWorkingDirectory;
  }

  function normalizeReusableTaskFilesModified(value) {
    const parsed = typeof value === 'string'
      ? (() => { try { return JSON.parse(value); } catch { return []; } })()
      : value;
    if (!Array.isArray(parsed)) return [];
    return parsed
      .map((entry) => {
        if (typeof entry === 'string') return entry.trim();
        if (entry && typeof entry === 'object') {
          return String(entry.path || entry.file_path || entry.file || '').trim();
        }
        return '';
      })
      .filter(Boolean);
  }

  function reusableCompletedTaskHasFileEvidence(candidate) {
    return normalizeReusableTaskFilesModified(candidate?.files_modified).length > 0;
  }

  function findExistingPlanTaskSubmission(taskCore, {
    projectName,
    workingDirectory,
    workItemId,
    planTaskNumber,
    batchId = null,
    planPath = null,
    stalePendingMs = DEFAULT_STALE_PENDING_PLAN_GENERATION_MS,
  }) {
    if (!taskCore || typeof taskCore.listTasks !== 'function') {
      return null;
    }

    const normalizedWorkItemId = normalizeWorkItemId(workItemId);
    const normalizedPlanTaskNumber = Number.isInteger(Number(planTaskNumber))
      ? Number(planTaskNumber)
      : null;
    if (!normalizedWorkItemId || !normalizedPlanTaskNumber) {
      return null;
    }

    const workItemTag = `factory:work_item_id=${normalizedWorkItemId}`;
    const planTaskTag = `factory:plan_task_number=${normalizedPlanTaskNumber}`;
    const batchTag = normalizeOptionalString(batchId)
      ? `factory:batch_id=${batchId.trim()}`
      : null;

    let candidates = [];
    try {
      const queryCandidates = (options = {}) => taskCore.listTasks({
        ...options,
        tag: workItemTag,
        statuses: ['pending', 'pending_approval', 'queued', 'running', 'completed'],
        orderBy: 'created_at',
        orderDir: 'desc',
        limit: 100,
        columns: ['id', 'status', 'tags', 'created_at', 'started_at', 'metadata', 'working_directory', 'files_modified'],
      });

      candidates = queryCandidates({
        ...(projectName ? { project: projectName } : {}),
        ...(workingDirectory ? { workingDirectory } : {}),
      });

      if (candidates.length === 0 && (projectName || workingDirectory)) {
        candidates = queryCandidates();
      }
    } catch (error) {
      logger.debug({
        err: error.message,
        work_item_id: normalizedWorkItemId,
        plan_task_number: normalizedPlanTaskNumber,
      }, 'Unable to query reusable plan task submissions');
      return null;
    }

    const matching = candidates.filter((candidate) => (
      Array.isArray(candidate?.tags)
      && candidate.tags.includes(workItemTag)
      && candidate.tags.includes(planTaskTag)
      && reusableTaskMatchesPlanContext(candidate, { planPath, workingDirectory })
    ));
    if (matching.length === 0) {
      return null;
    }

    const prioritized = batchTag
      ? [
          ...matching.filter((candidate) => candidate.tags.includes(batchTag)),
          ...matching.filter((candidate) => !candidate.tags.includes(batchTag)),
        ]
      : matching;

    const active = prioritized.find((candidate) => {
      const activeStatus = candidate.status === 'running'
        || candidate.status === 'queued'
        || candidate.status === 'pending'
        || candidate.status === 'pending_approval';
      if (!activeStatus) {
        return false;
      }
      if (isStaleNeverStartedPendingPlanGenerationTask(candidate, stalePendingMs)) {
        logger.warn('Ignoring stale pending reusable plan task submission', {
          task_id: candidate.id,
          work_item_id: normalizedWorkItemId,
          plan_task_number: normalizedPlanTaskNumber,
          status: candidate.status,
          created_at: candidate.created_at || candidate.createdAt || null,
        });
        return false;
      }
      if (!activeReusableTaskMatchesWorkingDirectory(candidate, workingDirectory)) {
        logger.warn('Ignoring active reusable plan task from a different working directory', {
          task_id: candidate.id,
          work_item_id: normalizedWorkItemId,
          plan_task_number: normalizedPlanTaskNumber,
          status: candidate.status,
          expected_working_directory: workingDirectory || null,
          candidate_working_directory: candidate.working_directory || candidate.workingDirectory || null,
        });
        return false;
      }
      return true;
    });
    if (active) {
      return {
        task_id: active.id,
        status: active.status,
        same_batch: Boolean(batchTag && active.tags.includes(batchTag)),
      };
    }

    const completedCandidates = prioritized.filter((candidate) => candidate.status === 'completed');
    const completed = completedCandidates.find(reusableCompletedTaskHasFileEvidence)
      || completedCandidates[0];
    if (completed) {
      const result = {
        task_id: completed.id,
        status: completed.status,
        same_batch: Boolean(batchTag && completed.tags.includes(batchTag)),
      };
      if (completed.files_modified !== undefined) {
        result.files_modified = completed.files_modified;
      }
      return result;
    }

    return null;
  }

  function findActivePlanGenerationTask(taskCore, {
    projectId,
    workingDirectory,
    workItemId,
    stalePendingMs = DEFAULT_STALE_PENDING_PLAN_GENERATION_MS,
  }) {
    if (!taskCore || typeof taskCore.listTasks !== 'function') {
      return null;
    }

    const normalizedWorkItemId = normalizeWorkItemId(workItemId);
    const normalizedProjectId = projectId == null ? null : String(projectId).trim();
    if (!normalizedProjectId || !normalizedWorkItemId) {
      return null;
    }

    const workItemTag = `factory:work_item_id=${normalizedWorkItemId}`;
    const baseQuery = {
      tag: workItemTag,
      statuses: ACTIVE_PLAN_GENERATION_TASK_STATUSES,
      orderBy: 'created_at',
      orderDir: 'desc',
      limit: 50,
      columns: ['id', 'status', 'tags', 'metadata', 'created_at', 'started_at', 'error_output'],
    };
    const candidateQueries = [
      ...(workingDirectory ? [{ ...baseQuery, workingDirectory }] : []),
      baseQuery,
    ];

    const seen = new Set();
    for (const query of candidateQueries) {
      let candidates = [];
      try {
        candidates = taskCore.listTasks(query);
      } catch (error) {
        logger.debug('Unable to query active plan-generation tasks', {
          err: error.message,
          project_id: normalizedProjectId,
          work_item_id: normalizedWorkItemId,
        });
        continue;
      }

      for (const candidate of Array.isArray(candidates) ? candidates : []) {
        if (!candidate?.id || seen.has(candidate.id)) continue;
        seen.add(candidate.id);
        if (!isSchedulerOwnedPlanGenerationTask(candidate, {
          projectId: normalizedProjectId,
          workItemId: normalizedWorkItemId,
        })) {
          continue;
        }
        if (retireStalePendingPlanGenerationTask(taskCore, candidate, {
          projectId: normalizedProjectId,
          workItemId: normalizedWorkItemId,
          staleAfterMs: stalePendingMs,
          reason: 'duplicate_plan_generation_scan',
          requireSchedulerOwned: true,
        })) {
          continue;
        }

        const status = String(candidate.status || '').toLowerCase();
        if (ACTIVE_PLAN_GENERATION_TASK_STATUSES.includes(status)) {
          return candidate;
        }
      }
    }

    return null;
  }

  function getPlanGenerationTaskWorkItemId(task) {
    const metadata = getTaskMetadataObject(task);
    const fromMetadata = normalizeWorkItemId(metadata.work_item_id);
    if (fromMetadata) {
      return fromMetadata;
    }

    for (const tag of normalizeTaskTags(task)) {
      const match = /^factory:work_item_id=(.+)$/i.exec(tag);
      if (match) {
        return normalizeWorkItemId(match[1]);
      }
    }

    return null;
  }

  function findActiveProjectPlanGenerationTask(taskCore, {
    projectId,
    workingDirectory,
    excludeWorkItemId = null,
    stalePendingMs = DEFAULT_STALE_PENDING_PLAN_GENERATION_MS,
  }) {
    if (!taskCore || typeof taskCore.listTasks !== 'function') {
      return null;
    }

    const normalizedProjectId = projectId == null ? null : String(projectId).trim();
    if (!normalizedProjectId) {
      return null;
    }

    const excludedWorkItemId = normalizeWorkItemId(excludeWorkItemId);
    const projectTag = `factory:project_id=${normalizedProjectId}`;
    const baseQuery = {
      tag: projectTag,
      statuses: ACTIVE_PLAN_GENERATION_TASK_STATUSES,
      orderBy: 'created_at',
      orderDir: 'desc',
      limit: 50,
      columns: ['id', 'status', 'tags', 'metadata', 'created_at', 'started_at', 'error_output'],
    };
    const candidateQueries = [
      ...(workingDirectory ? [{ ...baseQuery, workingDirectory }] : []),
      baseQuery,
    ];

    const seen = new Set();
    for (const query of candidateQueries) {
      let candidates = [];
      try {
        candidates = taskCore.listTasks(query);
      } catch (error) {
        logger.debug('Unable to query active project plan-generation tasks', {
          err: error.message,
          project_id: normalizedProjectId,
        });
        continue;
      }

      for (const candidate of Array.isArray(candidates) ? candidates : []) {
        if (!candidate?.id || seen.has(candidate.id)) continue;
        seen.add(candidate.id);
        if (!isSchedulerOwnedPlanGenerationTask(candidate, { projectId: normalizedProjectId })) {
          continue;
        }
        if (retireStalePendingPlanGenerationTask(taskCore, candidate, {
          projectId: normalizedProjectId,
          staleAfterMs: stalePendingMs,
          reason: 'project_plan_generation_scan',
          requireSchedulerOwned: true,
        })) {
          continue;
        }

        const taskWorkItemId = getPlanGenerationTaskWorkItemId(candidate);
        if (excludedWorkItemId && taskWorkItemId === excludedWorkItemId) {
          continue;
        }

        const status = String(candidate.status || '').toLowerCase();
        if (ACTIVE_PLAN_GENERATION_TASK_STATUSES.includes(status)) {
          return {
            ...candidate,
            factory_work_item_id: taskWorkItemId,
          };
        }
      }
    }

    return null;
  }

  function buildProjectPlanGenerationBusyResult({
    project,
    instance,
    targetItem,
    planPath,
    activeTask,
  }) {
    const activeWorkItemId = getPlanGenerationTaskWorkItemId(activeTask);
    const status = activeTask?.status || 'running';
    logger.info('EXECUTE stage: deferred plan generation because another project plan task is active', {
      project_id: project.id,
      work_item_id: targetItem.id,
      active_work_item_id: activeWorkItemId,
      generation_task_id: activeTask?.id || null,
      task_status: status,
    });
    safeLogDecision({
      project_id: project.id,
      stage: LOOP_STATES.EXECUTE,
      action: 'plan_generation_deferred_project_active',
      reasoning: 'Another factory plan-generation task is already active for this project.',
      inputs: {
        ...getWorkItemDecisionContext(targetItem),
      },
      outcome: {
        reason: 'project_plan_generation_active',
        plan_path: planPath,
        generation_task_id: activeTask?.id || null,
        blocking_work_item_id: activeWorkItemId,
        task_status: status,
        ...getWorkItemDecisionContext(targetItem),
      },
      confidence: 1,
      batch_id: getDecisionBatchId(project, targetItem, null, instance),
    });

    return {
      reason: 'plan generation deferred while another project plan task is active',
      work_item: targetItem,
      stop_execution: true,
      next_state: LOOP_STATES.EXECUTE,
      paused_at_stage: null,
      stage_result: {
        status: 'deferred',
        reason: 'project_plan_generation_active',
        plan_path: planPath,
        generation_task_id: activeTask?.id || null,
        blocking_work_item_id: activeWorkItemId,
        task_status: status,
      },
    };
  }

  async function prepareAutoGeneratedPlanArtifactWorktree({
    project,
    instance = null,
    workItem,
  }) {
    if (!workItem?.id) {
      throw new Error('auto-generated plan worktree requires workItem.id');
    }
    const batchId = getFactorySubmissionBatchId(project, workItem, instance);
    if (!batchId) {
      throw new Error('auto-generated plan worktree requires a batch id');
    }

    const worktreeRunner = getWorktreeRunner();
    if (!worktreeRunner || typeof worktreeRunner.createForBatch !== 'function') {
      safeLogDecision({
        project_id: project.id,
        stage: LOOP_STATES.EXECUTE,
        action: 'plan_generation_worktree_unavailable',
        reasoning: 'Auto-generated plan artifacts require a factory worktree before writing plan files. Pausing instead of writing into the main checkout.',
        inputs: { ...getWorkItemDecisionContext(workItem) },
        outcome: {
          batch_id: batchId,
          plan_path: buildAutoGeneratedPlanPath(project, workItem),
        },
        confidence: 1,
        batch_id: batchId,
      });
      throw new Error('factory worktree runner unavailable for auto-generated plan artifact');
    }

    let activeWorktree = null;
    try {
      activeWorktree = typeof factoryWorktrees.getActiveWorktreeByBatchAndWorkItem === 'function'
        ? factoryWorktrees.getActiveWorktreeByBatchAndWorkItem(batchId, workItem.id)
        : null;
      if (!activeWorktree && typeof factoryWorktrees.getActiveWorktreeForWorkItem === 'function') {
        activeWorktree = factoryWorktrees.getActiveWorktreeForWorkItem(project.id, workItem.id);
      }
      if (!activeWorktree) {
        activeWorktree = factoryWorktrees.getActiveWorktreeByBatch(batchId);
      }
    } catch (error) {
      logger.debug('auto-generated plan worktree lookup failed', {
        project_id: project.id,
        work_item_id: workItem.id,
        batch_id: batchId,
        err: error.message,
      });
    }

    const activeWorktreePath = getFactoryWorktreePath(activeWorktree);
    let activeWorktreeAbandonedForFreshness = false;
    let preservedDirtyFallbackSuffix = null;
    if (activeWorktreePath && fs.existsSync(activeWorktreePath)) {
      if (!factoryWorktreeBelongsToWorkItem(activeWorktree, workItem)) {
        safeLogDecision({
          project_id: project.id,
          stage: LOOP_STATES.EXECUTE,
          action: 'plan_generation_worktree_reuse_skipped',
          reasoning: 'Skipped active batch worktree reuse because the row belongs to a different factory work item.',
          inputs: { ...getWorkItemDecisionContext(workItem) },
          outcome: {
            factory_worktree_id: activeWorktree.id,
            worktree_id: activeWorktree.vcWorktreeId,
            worktree_path: activeWorktreePath,
            branch: activeWorktree.branch,
            batch_id: batchId,
            active_work_item_id: getFactoryWorktreeWorkItemId(activeWorktree),
            requested_work_item_id: workItem.id,
          },
          confidence: 1,
          batch_id: batchId,
        });
      } else {
        const freshness = await ensureReusedFactoryWorktreeFresh({
          project,
          workItem,
          worktreeRecord: activeWorktree,
          worktreePath: activeWorktreePath,
          batchId,
          reuseContext: 'plan_generation',
        });
        if (!freshness.ok) {
          if (freshness.dirtyWorktree || freshness.preserveWorktree) {
            factoryWorktrees.markPreserved(
              activeWorktree.id,
              freshness.invalidWorktree
                ? 'invalid_git_metadata_before_plan_generation_fallback'
                : 'dirty_before_plan_generation_fallback',
            );
            preservedDirtyFallbackSuffix = freshness.fallbackSuffix || `preserved-dirty-${activeWorktree.id}`;
          } else {
            await abandonReusedFactoryWorktreeAfterFreshnessFailure({
              worktreeRunner,
              worktreeRecord: activeWorktree,
              reason: 'stale_rebase_failed_before_plan_generation',
            });
          }
          activeWorktreeAbandonedForFreshness = true;
        } else {
          safeLogDecision({
            project_id: project.id,
            stage: LOOP_STATES.EXECUTE,
            action: 'plan_generation_worktree_reused',
            reasoning: 'Reusing the active factory work-item worktree for auto-generated plan artifacts.',
            inputs: { ...getWorkItemDecisionContext(workItem) },
            outcome: {
              factory_worktree_id: activeWorktree.id,
              worktree_id: activeWorktree.vcWorktreeId,
              worktree_path: activeWorktreePath,
              branch: activeWorktree.branch,
              batch_id: batchId,
            },
            confidence: 1,
            batch_id: batchId,
          });
          prepareReusedFactoryWorktreeDependencies(activeWorktreePath, {
            project_id: project.id,
            work_item_id: workItem.id,
            batch_id: batchId,
            reuse_context: 'plan_generation',
          });
          return {
            batchId,
            worktreeRecord: activeWorktree,
            workingDirectory: activeWorktreePath,
            planPath: buildAutoGeneratedPlanPath(project, workItem, activeWorktreePath),
          };
        }
      }
    }

    if (activeWorktree && factoryWorktreeBelongsToWorkItem(activeWorktree, workItem) && !activeWorktreeAbandonedForFreshness) {
      safeLogDecision({
        project_id: project.id,
        stage: LOOP_STATES.EXECUTE,
        action: 'plan_generation_worktree_missing_abandoned',
        reasoning: 'Active factory work-item worktree was missing on disk before auto-generated plan artifact creation; marking abandoned.',
        inputs: { ...getWorkItemDecisionContext(workItem) },
        outcome: {
          factory_worktree_id: activeWorktree.id,
          worktree_id: activeWorktree.vcWorktreeId,
          worktree_path: activeWorktreePath,
          branch: activeWorktree.branch,
          batch_id: batchId,
        },
        confidence: 1,
        batch_id: batchId,
      });
    }

    if (activeWorktree && factoryWorktreeBelongsToWorkItem(activeWorktree, workItem) && !activeWorktreeAbandonedForFreshness) {
      try {
        factoryWorktrees.markAbandoned(activeWorktree.id, 'missing_before_plan_generation');
      } catch (error) {
        logger.warn('auto-generated plan worktree: failed to mark missing active worktree abandoned', {
          project_id: project.id,
          work_item_id: workItem.id,
          batch_id: batchId,
          factory_worktree_id: activeWorktree.id,
          worktree_path: activeWorktreePath,
          err: error.message,
        });
      }
    }

    let createdWorktree = null;
    try {
      createdWorktree = await worktreeRunner.createForBatch({
        project,
        workItem,
        batchId,
        featureNameSuffix: preservedDirtyFallbackSuffix,
      });
      const worktreeRecord = factoryWorktrees.recordWorktree({
        project_id: project.id,
        work_item_id: workItem.id,
        batch_id: batchId,
        vc_worktree_id: createdWorktree.id,
        branch: createdWorktree.branch,
        worktree_path: createdWorktree.worktreePath,
        base_branch: createdWorktree.baseBranch || createdWorktree.base_branch || null,
      });
      const worktreePath = getFactoryWorktreePath(worktreeRecord);
      safeLogDecision({
        project_id: project.id,
        stage: LOOP_STATES.EXECUTE,
        action: 'plan_generation_worktree_created',
        reasoning: `Created isolated worktree for auto-generated plan artifacts in factory batch ${batchId}.`,
        inputs: { ...getWorkItemDecisionContext(workItem) },
        outcome: {
          worktree_id: worktreeRecord.vcWorktreeId,
          factory_worktree_id: worktreeRecord.id,
          worktree_path: worktreePath,
          branch: worktreeRecord.branch,
          batch_id: batchId,
        },
        confidence: 1,
        batch_id: batchId,
      });
      return {
        batchId,
        worktreeRecord,
        workingDirectory: worktreePath,
        planPath: buildAutoGeneratedPlanPath(project, workItem, worktreePath),
      };
    } catch (error) {
      if (createdWorktree && typeof worktreeRunner.abandon === 'function') {
        try {
          await worktreeRunner.abandon({
            id: createdWorktree.id,
            branch: createdWorktree.branch,
            reason: 'plan_generation_worktree_persistence_failed',
          });
        } catch (cleanupErr) {
          logger.warn('auto-generated plan worktree cleanup failed after persistence error', {
            project_id: project.id,
            work_item_id: workItem.id,
            branch: createdWorktree.branch,
            err: cleanupErr.message,
          });
        }
      }
      safeLogDecision({
        project_id: project.id,
        stage: LOOP_STATES.EXECUTE,
        action: 'plan_generation_worktree_creation_failed',
        reasoning: `Could not create a worktree for auto-generated plan artifacts: ${error.message}. Pausing instead of writing into the main checkout.`,
        inputs: { ...getWorkItemDecisionContext(workItem) },
        outcome: {
          error: error.message,
          batch_id: batchId,
        },
        confidence: 1,
        batch_id: batchId,
      });
      throw error;
    }
  }

  function hasPlanPathCreationContext(planText, filePath) {
    const text = String(planText || '');
    const raw = String(filePath || '');
    const variants = [...new Set([raw, raw.replace(/\//g, '\\'), raw.replace(/\\/g, '/')])].filter(Boolean);
    for (const variant of variants) {
      let index = text.indexOf(variant);
      while (index >= 0) {
        const before = text.slice(Math.max(0, index - 180), index);
        const after = text.slice(index + variant.length, Math.min(text.length, index + variant.length + 100));
        const createVerbRe = /\b(?:create|scaffold|introduce|write)\b/gi;
        let isCreateTarget = false;
        for (const match of before.matchAll(createVerbRe)) {
          const betweenVerbAndTarget = before.slice(match.index + match[0].length);
          if (extractPlanDescriptionFilePaths(betweenVerbAndTarget).length === 0) {
            isCreateTarget = true;
            break;
          }
        }
        if (isCreateTarget || /^\s*(?:as\s+)?(?:a\s+)?(?:new|created|generated)\s+(?:file|module|script|test|doc)/i.test(after)) {
          return true;
        }
        index = text.indexOf(variant, index + variant.length);
      }
    }
    return false;
  }

  function isEphemeralGeneratedPlanTarget(filePath) {
    const normalized = String(filePath || '').trim().replace(/\\/g, '/').replace(/^\.\//, '').toLowerCase();
    return normalized.startsWith('.tmp/')
      || normalized.startsWith('tmp/')
      || normalized.startsWith('temp/');
  }

  function shouldReplaceExistingPlanPath(originalFile, replacementFile, workItem, hardScopeFiles = []) {
    const originalLower = String(originalFile || '').replace(/\\/g, '/').toLowerCase();
    const replacementLower = String(replacementFile || '').replace(/\\/g, '/').toLowerCase();
    const hardScope = new Set((hardScopeFiles || []).map((file) => String(file || '').replace(/\\/g, '/').toLowerCase()));
    if (!originalLower || !replacementLower || hardScope.has(originalLower)) return false;
    return false;
  }

  function replacePlanPathLiteral(planText, originalFile, replacementFile) {
    let out = String(planText || '');
    const original = String(originalFile || '').replace(/\\/g, '/');
    const replacement = String(replacementFile || '').replace(/\\/g, '/');
    const variants = [...new Set([original, original.replace(/\//g, '\\')])].filter(Boolean);
    for (const variant of variants) {
      const re = new RegExp(`(^|[^A-Za-z0-9_.\\\\/-])${escapeRegExpLiteral(variant)}(?![A-Za-z0-9_.\\\\/-])`, 'g');
      out = out.replace(re, (_match, prefix) => `${prefix}${replacement}`);
    }
    return out;
  }

  function chooseMissingPlanPathReplacement(normalized, alternateFiles = [], relatedPool = [], workItem = null) {
    const candidates = [...new Set(
      (alternateFiles || [])
        .concat(relatedPool || [])
        .map((file) => String(file || '').replace(/\\/g, '/'))
        .filter(Boolean)
    )];
    if (candidates.length === 0) return null;
    const normalizedDir = path.posix.dirname(String(normalized || '').replace(/\\/g, '/').toLowerCase());
    const sameDirectoryAlternate = (alternateFiles || [])
      .map((file) => String(file || '').replace(/\\/g, '/'))
      .find((file) => path.posix.dirname(file.toLowerCase()) === normalizedDir);
    if (sameDirectoryAlternate) return sameDirectoryAlternate;
    return chooseRelatedReplacementFile(normalized, candidates, workItem) || candidates[0] || null;
  }

  function normalizeGeneratedPlanFileReferences(taskSection, workItem, project) {
    const projectPath = project?.path;
    if (!projectPath) return taskSection;

    const rawPaths = extractPlanDescriptionFilePaths(taskSection);
    if (rawPaths.length === 0) return taskSection;

    let out = String(taskSection || '');
    const details = collectArchitectScopeDetails(workItem, projectPath);
    const hardScopeFiles = details.hardScopeFiles || [];
    const alternateFilesByPath = new Map();
    const alternateFiles = rawPaths.flatMap((rawPath) => {
      const normalized = normalizePlanProjectRelativePath(rawPath, projectPath);
      if (!normalized) return [];
      const candidates = discoverExistingFileAlternates(projectPath, normalized, 4);
      if (candidates.length > 0) {
        alternateFilesByPath.set(normalized, candidates);
      }
      return candidates;
    });
    const relatedPool = alternateFiles
      .concat(discoverRelatedProjectFiles(projectPath, workItem, rawPaths, 12))
      .concat(details.relatedFiles || [])
      .filter((file, index, arr) => file && arr.indexOf(file) === index);
    for (const rawPath of [...new Set(rawPaths)]) {
      const exactBasenameMatch = findUniqueProjectFileByBasename(projectPath, rawPath);
      if (exactBasenameMatch) {
        out = replacePlanPathLiteral(out, rawPath, exactBasenameMatch);
        continue;
      }

      const normalized = normalizePlanProjectRelativePath(rawPath, projectPath);
      if (!normalized) continue;
      const exists = projectFileExists(projectPath, normalized);
      const alternateFilesForPath = alternateFilesByPath.get(normalized) || [];
      const replacement = exists
        ? chooseRelatedReplacementFile(normalized, relatedPool, workItem)
        : chooseMissingPlanPathReplacement(normalized, alternateFilesForPath, relatedPool, workItem);
      if (!replacement || replacement === normalized) continue;

      const creationContext = hasPlanPathCreationContext(out, rawPath);
      const ephemeralGeneratedTarget = isEphemeralGeneratedPlanTarget(normalized);
      const shouldReplace = exists
        ? shouldReplaceExistingPlanPath(normalized, replacement, workItem, hardScopeFiles)
        : (ephemeralGeneratedTarget || !creationContext || (isPlanTestPath(normalized) && isPlanTestPath(replacement)));
      if (!shouldReplace) continue;

      out = replacePlanPathLiteral(out, rawPath, replacement);
    }

    return out;
  }

  function extractPlanMarkdownCandidate(value) {
    const text = extractTextContent(value).trim();
    if (!text) {
      return '';
    }
    if (looksLikeDirectPlanMarkdown(text)) {
      return text;
    }
    return extractCodexFinalAnswerFromTranscript(text);
  }

  function extractPlanGenerationRawMarkdown(generationTask, awaitResult = null) {
    return extractPlanMarkdownCandidate(generationTask?.output)
      || extractCodexFinalAnswerFromTranscript(generationTask?.error_output)
      || extractPlanMarkdownCandidate(awaitResult);
  }

  function getSideWrittenPlanCandidatePaths(planPath) {
    const normalizedPlanPath = normalizeOptionalString(planPath);
    if (!normalizedPlanPath) {
      return [];
    }

    let resolvedPlanPath;
    try {
      resolvedPlanPath = path.resolve(normalizedPlanPath);
    } catch {
      return [];
    }

    const parentDir = path.dirname(resolvedPlanPath);
    if (path.basename(parentDir).toLowerCase() !== 'auto-generated') {
      return [];
    }

    const plansDir = path.dirname(parentDir);
    const fileName = path.basename(resolvedPlanPath);
    const candidates = [
      path.join(plansDir, fileName),
    ];
    const seen = new Set([resolvedPlanPath.toLowerCase()]);
    return candidates.filter((candidate) => {
      const key = path.resolve(candidate).toLowerCase();
      if (seen.has(key)) {
        return false;
      }
      seen.add(key);
      return true;
    });
  }

  function recoverTerminalPlanGenerationMarkdown({
    generationTask,
    awaitResult = null,
    planPath,
    workItem,
    project,
  } = {}) {
    const rawPlanMarkdown = extractPlanGenerationRawMarkdown(generationTask, awaitResult);
    const normalizedFromOutput = normalizeAutoGeneratedPlanMarkdown(rawPlanMarkdown, workItem, project);
    if (normalizedFromOutput) {
      return {
        source: 'task_output',
        sourcePath: null,
        markdown: normalizedFromOutput,
      };
    }

    for (const candidatePath of getSideWrittenPlanCandidatePaths(planPath)) {
      try {
        const stat = fs.statSync(candidatePath);
        if (!stat.isFile() || stat.size <= 0 || stat.size > 1024 * 1024) {
          continue;
        }
        const candidateMarkdown = fs.readFileSync(candidatePath, 'utf8');
        const normalizedFromFile = normalizeAutoGeneratedPlanMarkdown(candidateMarkdown, workItem, project);
        if (normalizedFromFile) {
          return {
            source: 'side_written_file',
            sourcePath: candidatePath,
            markdown: normalizedFromFile,
          };
        }
      } catch {
        // Candidate was not written or was removed while we inspected it.
      }
    }

    return null;
  }

  function cleanupRecoveredSideWrittenPlan(recoveredPlan, planPath) {
    if (!recoveredPlan || recoveredPlan.source !== 'side_written_file' || !recoveredPlan.sourcePath) {
      return;
    }

    let sourcePath;
    let expectedPath;
    try {
      sourcePath = path.resolve(recoveredPlan.sourcePath);
      expectedPath = path.resolve(planPath);
    } catch {
      return;
    }

    if (sourcePath.toLowerCase() === expectedPath.toLowerCase()) {
      return;
    }

    try {
      if (fs.existsSync(sourcePath)) {
        fs.unlinkSync(sourcePath);
      }
    } catch (error) {
      logger.warn('EXECUTE stage: failed to remove side-written generated plan after adoption', {
        plan_path: expectedPath,
        side_written_plan_path: sourcePath,
        err: error.message,
      });
    }
  }

  function isAlreadyRemoteRouted(fullLine, commandIndex) {
    const prefix = fullLine.slice(0, commandIndex).toLowerCase();
    const remoteIndex = prefix.lastIndexOf('torque-remote');
    if (remoteIndex === -1) return false;
    const separatorIndex = Math.max(
      prefix.lastIndexOf(';'),
      prefix.lastIndexOf('&&'),
      prefix.lastIndexOf('|'),
      prefix.lastIndexOf('\n'),
    );
    return remoteIndex > separatorIndex;
  }

  function prefixUnroutedHeavyCommand(line, pattern) {
    return String(line || '').replace(pattern, (match, leading, command, offset, fullLine) => {
      const commandIndex = offset + leading.length;
      if (isAlreadyRemoteRouted(fullLine, commandIndex)) {
        return match;
      }
      return `${leading}torque-remote ${command}`;
    });
  }

  function routeHeavyValidationCommands(value) {
    const lines = String(value || '').split(/\r?\n/);
    let changed = false;
    const routed = lines.map((line) => {
      if (!findHeavyLocalValidationCommand(line)) {
        return line;
      }

      let next = prefixUnroutedHeavyCommand(line, /(^|[^\w-])(dotnet\s+(?:build|test)\b)/gi);
      next = prefixUnroutedHeavyCommand(next, /(^|[^\w-])((?:pwsh|powershell(?:\.exe)?)(?:\s+-file)?\s+(?:\.?[\\/])?scripts[\\/](?:build|test)\.ps1\b)/gi);
      next = prefixUnroutedHeavyCommand(next, /(^|[^\w-])((?:bash|sh)\s+(?:\.?[\\/])?scripts[\\/](?:build|test)\.sh\b)/gi);
      if (next !== line) {
        changed = true;
      }
      return next;
    });

    return changed ? routed.join('\n') : value;
  }

  function dedupeValidationCommandTargetText(text) {
    const seen = new Set();
    let changed = false;
    VALIDATION_TARGET_PATH_RE.lastIndex = 0;
    const value = String(text || '').replace(VALIDATION_TARGET_PATH_RE, (match) => {
      const normalized = String(match || '').replace(/\\/g, '/').toLowerCase();
      if (seen.has(normalized)) {
        changed = true;
        return '';
      }
      seen.add(normalized);
      return match;
    }).replace(/[ \t]{2,}/g, ' ').replace(/[ \t]+$/g, '');
    return { value, changed };
  }

  function dedupeValidationCommandTargets(value) {
    const lines = String(value || '').split(/\r?\n/);
    let changed = false;
    const nextLines = lines.map((line) => {
      if (!VALIDATION_COMMAND_LINE_RE.test(line)) return line;
      let handledBacktickCommand = false;
      let lineChanged = false;
      const backtickNext = line.replace(/`([^`]+)`/g, (match, inner) => {
        if (!VALIDATION_COMMAND_LINE_RE.test(inner)) {
          return match;
        }
        handledBacktickCommand = true;
        const deduped = dedupeValidationCommandTargetText(inner);
        lineChanged = lineChanged || deduped.changed;
        return `\`${deduped.value}\``;
      });
      if (handledBacktickCommand) {
        changed = changed || lineChanged;
        return backtickNext;
      }

      const boundary = line.search(/\b(?:success criteria|acceptance criteria|expected(?: passing)? result)\b/i);
      const commandEnd = boundary >= 0 ? boundary : line.length;
      const deduped = dedupeValidationCommandTargetText(line.slice(0, commandEnd));
      changed = changed || deduped.changed;
      return `${deduped.value}${line.slice(commandEnd)}`;
    });
    return changed ? nextLines.join('\n') : value;
  }

  function getPrimaryAllowedFile(workItem) {
    const constraints = getWorkItemConstraintsObject(workItem);
    const allowedFiles = Array.isArray(constraints.allowed_files)
      ? constraints.allowed_files.map((file) => String(file || '').trim()).filter(Boolean)
      : [];
    return allowedFiles[0] || null;
  }

  function getPrimaryPlanReferenceFile(value, workItem) {
    // When the work item has an explicit constraints.allowed_files list,
    // prefer that as the canonical "where this work happens" path. Plan
    // text frequently references the bare filename (e.g. "Foo.cs" pulled
    // from the task title) which extractPlanDescriptionFilePaths returns
    // ahead of the full repo-relative path; without this preference the
    // qualify replacements emit `Foo.cs` instead of `subdir/Foo.cs` and
    // break test assertions plus actual prompt usefulness.
    const fromAllowed = getPrimaryAllowedFile(workItem);
    if (fromAllowed) return fromAllowed;
    const fromPlan = extractPlanDescriptionFilePaths(value)[0];
    if (fromPlan) return fromPlan;
    return collectArchitectScopeFiles(workItem)[0] || null;
  }

  function replaceUnqualifiedPlanPhrase(text, pattern, replacement) {
    return String(text || '').replace(pattern, replacement);
  }

  function isAutoGeneratedPlanStructureLine(line) {
    const value = String(line || '').trim();
    return /^##\s+Task\s+\d+:/i.test(value)
      || /^-\s+\[\s*\]\s+\*\*Step\s+\d+:/i.test(value);
  }

  function getLineSpecificPlanReferenceFile(line, workItem, planFilePaths = [], fallbackFile = null) {
    const rawValue = String(line || '');
    const value = rawValue.toLowerCase();
    const basenameMatch = (planFilePaths || []).find((file) => {
      const normalized = String(file || '').replace(/\\/g, '/');
      const rawBase = path.posix.basename(normalized);
      const base = rawBase.toLowerCase();
      if (!base) return false;
      const rawStem = rawBase.replace(/\.[^.]+$/, '');
      const stem = rawStem.toLowerCase();
      return value.includes(base)
        || ((/[A-Z_]/.test(rawStem) || rawStem.length >= 12) && stem.length >= 4 && value.includes(stem));
    });
    if (basenameMatch) return basenameMatch;

    if (/\b(?:doc|docs|documentation|readme)\b/i.test(line)) {
      const docPath = (planFilePaths || [])
        .concat(collectArchitectScopeFiles(workItem))
        .find((file) => /(?:^|[\\/])docs?[\\/]|(?:^|[\\/])README\.md$|\.md$/i.test(String(file || '')));
      if (docPath) return docPath;
    }

    return fallbackFile;
  }

  function qualifyAutoGeneratedPlanStructureLine(line, workItem, planFilePaths, fallbackFile) {
    if (!isAutoGeneratedPlanStructureLine(line) || hasObjectLevelDetail(line)) {
      return line;
    }

    const referenceFile = getLineSpecificPlanReferenceFile(line, workItem, planFilePaths, fallbackFile);
    if (!referenceFile) return line;
    const fileRef = `\`${referenceFile}\``;
    let out = String(line || '');
    out = replaceUnqualifiedPlanPhrase(out, /\bimprov(?:e|es|ed|ing)\b/gi, `clarify ${fileRef}`);
    out = replaceUnqualifiedPlanPhrase(out, /\bupdat(?:e|es|ed|ing)\b/gi, `edit ${fileRef}`);
    out = replaceUnqualifiedPlanPhrase(out, /\bmodif(?:y|ies|ied|ying)\b/gi, `edit ${fileRef}`);
    out = replaceUnqualifiedPlanPhrase(out, /\bclean\s+up\b/gi, `simplify ${fileRef}`);
    out = replaceUnqualifiedPlanPhrase(out, /\bas\s+needed\b/gi, `within ${fileRef}`);
    return out;
  }

  function qualifyAutoGeneratedVaguePlanLanguage(value, workItem) {
    const primaryFile = getPrimaryPlanReferenceFile(value, workItem);
    if (!primaryFile) return value;

    const fileRef = `\`${primaryFile}\``;
    let text = String(value || '');
    text = replaceUnqualifiedPlanPhrase(
      text,
      /\bmodif(?:y|ies|ied|ying)\s+the\s+test\s+bodies\s+to\s+improv(?:e|es|ed|ing)\s+readability\b/gi,
      `Edit ${fileRef} test bodies to clarify statement grouping`
    );
    text = replaceUnqualifiedPlanPhrase(
      text,
      /\bimprov(?:e|es|ed|ing)\s+code\s+formatting\s+and\s+clarity\b/gi,
      `clarifying formatting in ${fileRef}`
    );
    text = replaceUnqualifiedPlanPhrase(
      text,
      /\bimprov(?:e|es|ed|ing)\s+readability\b/gi,
      `clarify statement grouping in ${fileRef}`
    );
    const planFilePaths = extractPlanDescriptionFilePaths(text);
    text = text
      .split(/(\r?\n)/)
      .map((part) => (/^\r?\n$/.test(part)
        ? part
        : qualifyAutoGeneratedPlanStructureLine(part, workItem, planFilePaths, primaryFile)))
      .join('');
    return text;
  }

  function workItemNeedsImplementationPlan(workItem) {
    const title = String(workItem?.title || '').trim();
    const text = `${title}\n${workItem?.description || ''}`;
    return PLAN_GENERATION_IMPLEMENTATION_SIGNAL_RE.test(text)
      && !PLAN_GENERATION_INVESTIGATION_TITLE_RE.test(title);
  }

  function isGeneratedAnalysisOnlyTask(task) {
    const title = String(task?.title || '').trim();
    const body = String(task?.body || '');
    if (!PLAN_GENERATION_ANALYSIS_TASK_TITLE_RE.test(title)) return false;

    const nonCommitBody = stripAutoGeneratedCommitSteps(body);
    return !PLAN_GENERATION_CHANGE_STEP_RE.test(nonCommitBody)
      || /\b(?:identify|analy[sz]e|locate|inspect|examine|research|read|search|find)\b/i.test(title);
  }

  function buildAnalysisImplementationPathContext(task, workItem, project, planFilePaths = []) {
    const details = project?.path ? collectArchitectScopeDetails(workItem, project.path) : null;
    const trustedContextPaths = details
      ? (details.scopeFiles || []).concat(details.relatedFiles || [])
      : collectArchitectScopeFiles(workItem);
    const candidateContextPaths = details ? (details.candidateFiles || []) : [];
    const contextPaths = trustedContextPaths.length > 0 ? trustedContextPaths : candidateContextPaths;
    if (contextPaths.length > 0) {
      return {
        paths: contextPaths,
        contextPreferred: true,
        hardScopeCount: (details?.hardScopeFiles || []).length,
      };
    }

    return {
      paths: getTaskSpecificityFilePaths(task, workItem, planFilePaths),
      contextPreferred: false,
      hardScopeCount: 0,
    };
  }

  function stripAutoGeneratedCommitSteps(body) {
    const lines = String(body || '').split(/\r?\n/);
    const out = [];
    let skippingCommitStep = false;

    for (const line of lines) {
      const stepMatch = line.match(/^\s*-\s*\[\s*\]\s*\*\*Step\s+\d+[A-Za-z]?\s*[:.]\s*([^*]+?)\s*\*\*/i);
      const taskHeading = /^##\s+Task\s+\d+\s*:/i.test(line);
      if (taskHeading) {
        skippingCommitStep = false;
      }

      if (stepMatch) {
        skippingCommitStep = /\bcommit\b/i.test(stepMatch[1] || '');
        if (skippingCommitStep) {
          continue;
        }
      }

      if (skippingCommitStep) {
        continue;
      }
      if (/^\s*git\s+commit\s+-m\b/i.test(line.trim())) {
        continue;
      }

      out.push(line);
    }

    return out.join('\n').replace(/\n{3,}/g, '\n\n').trim();
  }

  function renumberAutoGeneratedSteps(body) {
    let next = 1;
    return String(body || '').replace(
      /^(\s*-\s*\[\s*\]\s*\*\*Step\s+)\d+[A-Za-z]?(\s*[:.])/gmi,
      (_match, prefix, suffix) => `${prefix}${next++}${suffix}`
    );
  }

  function summarizeWorkItemImplementationGoal(workItem, project = null) {
    const raw = String(workItem?.description || workItem?.title || '').replace(/\s+/g, ' ').trim();
    if (!raw) {
      return `work item #${workItem?.id || 'current'} is implemented`;
    }

    const firstSentence = raw.match(/^(.{40,360}?[.!?])\s/)?.[1] || raw.slice(0, 320);
    const goal = firstSentence.replace(/\s+$/g, '').replace(/[;:,]+$/g, '');
    return normalizeGeneratedPlanFileReferences(goal, workItem, project);
  }

  function buildImplementationTaskFromAnalysis(task, workItem, project, planFilePaths = []) {
    const {
      paths,
      contextPreferred,
      hardScopeCount,
    } = buildAnalysisImplementationPathContext(task, workItem, project, planFilePaths);
    const uniquePaths = [...new Set(paths.map((file) => String(file || '').replace(/\\/g, '/')).filter(Boolean))];
    const testFiles = uniquePaths.filter((file) => isPlanTestPath(file));
    const implementationFiles = uniquePaths.filter((file) => !isPlanTestPath(file));
    const maxScopedFiles = contextPreferred && hardScopeCount === 0 ? 1 : 4;
    const scopedFiles = (implementationFiles.length > 0 ? implementationFiles : uniquePaths).slice(0, maxScopedFiles);
    const primaryFile = scopedFiles[0] || collectArchitectScopeFiles(workItem, project?.path)[0] || 'the existing implementation file';
    const validationTask = {
      title: task?.title || '',
      body: [...scopedFiles, ...testFiles.slice(0, 1)].map((file) => `\`${file}\``).join(' '),
    };
    const validation = buildTaskValidationDetail(validationTask, workItem, project, uniquePaths);
    const successDetail = buildWorkItemSuccessDetail(workItem);
    const goal = summarizeWorkItemImplementationGoal(workItem, project);
    const fileList = formatPlanDescriptionFileList([...scopedFiles, ...testFiles.slice(0, 1)], 5)
      || `\`${primaryFile}\``;
    const testFile = testFiles[0];
    const body = [
      '- [ ] **Step 1: Implement scoped behavior**',
      '',
      `    Edit ${fileList}. Estimated scope: single focused change across ${Math.max(1, scopedFiles.length)} file${scopedFiles.length === 1 ? '' : 's'}. Acceptance criteria: ${successDetail}. The implementation must satisfy this work item goal: ${goal}`,
      '',
      '- [ ] **Step 2: Cover the behavior**',
      '',
      testFile
        ? `    Add or adjust targeted coverage in \`${testFile}\` for the new behavior. Estimated scope: one focused test file. The tests must assert the requested success path plus relevant validation/error behavior.`
        : `    Add or adjust the nearest targeted test for \`${primaryFile}\`. Estimated scope: one focused test file. The tests must assert the requested success path plus relevant validation/error behavior.`,
      '',
      '- [ ] **Step 3: Validate targeted change**',
      '',
      `    Run \`${validation}\` from the repository root. Success criteria: the command should pass and failures must be tied to ${fileList}.`,
    ].join('\n');

    return {
      title: buildImplementationTaskTitle(workItem),
      body,
    };
  }

  function parseAutoGeneratedTaskSectionBlocks(taskSection) {
    const content = String(taskSection || '').trim();
    if (!content) return [];
    const headingRe = /^## Task\s+(\d+):\s*(.*)$/gm;
    const headings = Array.from(content.matchAll(headingRe)).map((match) => ({
      number: Number(match[1]),
      title: (match[2] || '').trim(),
      start: match.index,
      headerLength: match[0].length,
    }));

    return headings.map((heading, index) => {
      const bodyStart = heading.start + heading.headerLength;
      const bodyEnd = index + 1 < headings.length ? headings[index + 1].start : content.length;
      return {
        number: heading.number,
        title: heading.title,
        body: content.slice(bodyStart, bodyEnd).trim(),
      };
    });
  }

  function rebuildAutoGeneratedTaskSection(tasks) {
    return tasks.map((task, index) => {
      const body = renumberAutoGeneratedSteps(stripAutoGeneratedCommitSteps(task.body));
      return `## Task ${index + 1}: ${task.title}\n\n${body}`.trimEnd();
    }).join('\n\n');
  }

  function normalizeAutoGeneratedImplementationTaskShape(taskSection, workItem, project) {
    const tasks = parseAutoGeneratedTaskSectionBlocks(taskSection);
    if (tasks.length === 0) return taskSection;

    const needsImplementation = workItemNeedsImplementationPlan(workItem);
    const planFilePaths = extractPlanDescriptionFilePaths(taskSection);
    let changed = false;
    const normalizedTasks = tasks.map((task, index) => {
      const strippedBody = stripAutoGeneratedCommitSteps(task.body);
      if (strippedBody !== String(task.body || '').trim()) {
        changed = true;
      }

      if (needsImplementation && index === 0 && isGeneratedAnalysisOnlyTask({ ...task, body: strippedBody })) {
        changed = true;
        return buildImplementationTaskFromAnalysis({ ...task, body: strippedBody }, workItem, project, planFilePaths);
      }

      return {
        title: task.title,
        body: strippedBody,
      };
    });

    return changed ? rebuildAutoGeneratedTaskSection(normalizedTasks) : taskSection;
  }

  function normalizeAutoGeneratedPlanMarkdown(markdown, workItem, project) {
    const raw = convertFencedBlocksToIndented(unwrapWholeMarkdownFence(markdown));
    // Accept common variations: "## Task 1:", "## Task 1.", "## Task 1 -",
    // "### Task 1:", "## Step 1:", "## 1.", "## 1:"
    const taskMatch = raw.match(/^#{2,3}\s+(?:Task|Step)?\s*\d+\s*[:.—-]\s*.+$/m)
      || raw.match(/^#{2,3}\s+\d+[.:]\s*.+$/m);
    if (!taskMatch || typeof taskMatch.index !== 'number') {
      const numberedSummaryPlan = buildPlanFromNumberedTaskSummary(raw, workItem, project);
      if (numberedSummaryPlan) {
        return normalizeAutoGeneratedPlanMarkdown(numberedSummaryPlan, workItem, project);
      }
      return buildPlanFromFileEditsProposal(markdown, workItem, project);
    }

    const titleMatch = raw.match(/^#\s+(.+)$/m);
    const goalMatch = raw.match(/\*\*Goal:\*\*\s*([^\n]+)/i);
    const techStackMatch = raw.match(/\*\*Tech Stack:\*\*\s*([^\n]+)/i);
    let taskSection = normalizeGeneratedPlanFileReferences(
      trimPromptEchoTail(raw.slice(taskMatch.index).trim()),
      workItem,
      project
    );
    taskSection = normalizeAutoGeneratedImplementationTaskShape(taskSection, workItem, project);
    taskSection = qualifyAutoGeneratedVaguePlanLanguage(taskSection, workItem);
    taskSection = dedupeValidationCommandTargets(taskSection);
    taskSection = routeHeavyValidationCommands(taskSection);
    taskSection = dedupeValidationCommandTargets(routeHeavyValidationCommands(augmentAutoGeneratedTaskSpecificity(taskSection, workItem, project)));
    const lines = [
      `# ${(titleMatch?.[1] || `${workItem?.title || `Work Item ${workItem?.id}`} Plan`).trim()}`,
      '',
      `**Source:** auto-generated from work_item #${workItem?.id}`,
    ];

    if (goalMatch?.[1]?.trim()) {
      lines.push(`**Goal:** ${goalMatch[1].trim()}`);
    }

    const inferredTechStack = inferAutoGeneratedPlanTechStack(project?.path);
    const modelTechStack = techStackMatch?.[1]?.trim();
    const normalizedTechStack = inferredTechStack && inferredTechStack !== 'application code'
      ? inferredTechStack
      : (modelTechStack || inferredTechStack || 'application code');
    lines.push(`**Tech Stack:** ${normalizedTechStack.trim()}`);
    lines.push('', taskSection);

    return `${lines.join('\n').replace(/\n{3,}/g, '\n\n').trim()}\n`;
  }

  function getPlanReviewProvidersHealth() {
    try {
      const providerRoutingCore = require('../db/provider/routing-core');
      const serverConfig = require('../config');
      const providerNames = ['claude-cli', 'anthropic', 'deepinfra'];

      return providerNames.map((providerName) => {
        let providerConfig = null;
        try {
          providerConfig = providerRoutingCore.getProvider(providerName);
        } catch {
          providerConfig = null;
        }

        const apiKeyConfigured = providerName === 'claude-cli'
          ? Boolean(serverConfig.getApiKey('anthropic'))
          : Boolean(serverConfig.getApiKey(providerName));
        const enabled = providerName === 'anthropic'
          ? (providerConfig ? Boolean(providerConfig.enabled) : apiKeyConfigured)
          : Boolean(providerConfig?.enabled);

        return {
          provider: providerName,
          enabled,
          healthy: typeof providerRoutingCore.isProviderHealthy === 'function'
            ? providerRoutingCore.isProviderHealthy(providerName)
            : true,
          api_key_configured: apiKeyConfigured,
        };
      });
    } catch (error) {
      logger.debug({ err: error.message }, 'Unable to resolve plan review providers');
      return [];
    }
  }

  async function reviewAutoGeneratedPlan(project, workItem, planContent) {
    const providerHealth = getPlanReviewProvidersHealth();
    const generatorProvider = getStoredPlanGeneratorProvider(workItem);
    const selectedReviewers = selectReviewers(providerHealth, generatorProvider);
    if (selectedReviewers.length === 0) {
      return {
        overall: 'approve',
        reviews: [],
        skipped: true,
      };
    }

    const { handleSmartSubmitTask } = require('../handlers/integration/routing');
    const { handleAwaitTask } = require('../handlers/workflow/await');
    const taskCore = require('../db/task-core');
    const reviewer = createPlanReviewer({
      submit: async (args) => {
        const result = await handleSmartSubmitTask({
          ...args,
          project: 'factory-review',
          working_directory: project.path || process.cwd(),
          task_metadata: {
            // Inject the project's provider_lane_policy so the smart-routing
            // chain filter (handlers/integration/routing.js) keeps the
            // reviewer task on the project's allowed providers. Without this,
            // a project pinned to ollama (e.g. example-project) silently leaked
            // reviewer work to whatever the routing template's default chain
            // picked — observed 2026-04-29 with Codex running example-project-tagged
            // reviewer tasks despite enforce_handoffs:true.
            ...buildProviderLaneTaskMetadata(project || {}),
            ...(args.task_metadata || {}),
          },
        });
        return { task_id: result?.task_id || null, content: result?.content || [] };
      },
      awaitTask: async (args) => {
        const awaitResult = await handleAwaitTask(args);
        const task = taskCore.getTask(args.task_id);

        return {
          task_id: args.task_id,
          status: task?.status || 'failed',
          output: extractTextContent(task?.output) || extractTextContent(awaitResult),
          error: task?.error_output || extractTextContent(awaitResult) || null,
        };
      },
      getProvidersHealth: () => providerHealth,
    });

    safeLogDecision({
      project_id: project.id,
      stage: LOOP_STATES.PLAN,
      action: 'plan_review_started',
      reasoning: `submitted plan review to ${selectedReviewers.length} reviewer(s)`,
      inputs: {
        ...getWorkItemDecisionContext(workItem),
        reviewer_count: selectedReviewers.length,
      },
      outcome: {
        reviewers: selectedReviewers.map((entry) => entry.name),
        reviewer_count: selectedReviewers.length,
      },
      confidence: 1,
      batch_id: getDecisionBatchId(project, workItem),
    });

    const result = await reviewer.review({ workItem, planContent });
    for (const review of result.reviews) {
      safeLogDecision({
        project_id: project.id,
        stage: LOOP_STATES.PLAN,
        action: 'plan_review_verdict',
        reasoning: `reviewer=${review.name} verdict=${review.verdict}`,
        inputs: {
          ...getWorkItemDecisionContext(workItem),
          reviewer: review.name,
        },
        outcome: {
          reviewer: review.name,
          provider: review.provider,
          verdict: review.verdict,
          confidence: review.confidence,
          concerns: review.concerns,
          suggestions: review.suggestions,
          task_id: review.task_id || null,
          reason: review.reason || null,
        },
        confidence: 1,
        batch_id: getDecisionBatchId(project, workItem),
      });
    }

    safeLogDecision({
      project_id: project.id,
      stage: LOOP_STATES.PLAN,
      action: 'plan_review_aggregated',
      reasoning: `overall=${result.overall}`,
      inputs: {
        ...getWorkItemDecisionContext(workItem),
        reviewer_count: result.reviews.length,
      },
      outcome: {
        overall: result.overall,
        reviewer_count: result.reviews.length,
        has_warnings: result.overall === 'request_changes',
        blocked: result.overall === 'block',
      },
      confidence: 1,
      batch_id: getDecisionBatchId(project, workItem),
    });

    if (result.overall === 'block') {
      logger.warn('PLAN review blocked execution of auto-generated plan', {
        project_id: project.id,
        work_item_id: workItem.id,
        reviewer_count: result.reviews.length,
      });
    } else if (result.overall === 'request_changes') {
      logger.warn('PLAN review requested changes but execution will proceed', {
        project_id: project.id,
        work_item_id: workItem.id,
        reviewer_count: result.reviews.length,
      });
    } else {
      logger.info('PLAN review approved auto-generated plan', {
        project_id: project.id,
        work_item_id: workItem.id,
        reviewer_count: result.reviews.length,
      });
    }

    return result;
  }

  function lintAutoGeneratedPlan(project, workItem, planContent) {
    const lintResult = architectRunner.lintPlanContent(planContent);
    const descriptionQuality = scoreAutoGeneratedPlanDescriptions(planContent);
    const batchId = getDecisionBatchId(project, workItem);

    if (lintResult.errors.length > 0) {
      logger.warn('PLAN lint rejected auto-generated plan', {
        project_id: project.id,
        work_item_id: workItem?.id ?? null,
        error_count: lintResult.errors.length,
      });
      safeLogDecision({
        project_id: project.id,
        stage: LOOP_STATES.PLAN,
        action: 'plan_lint_rejected',
        reasoning: `plan lint rejected auto-generated plan with ${lintResult.errors.length} error(s)`,
        inputs: {
          ...getWorkItemDecisionContext(workItem),
        },
        outcome: {
          errors: lintResult.errors,
        },
        confidence: 1,
        batch_id: batchId,
      });
      return {
        blocked: true,
        lintResult,
        descriptionQuality,
      };
    }

    if (lintResult.warnings.length > 0) {
      logger.warn('PLAN lint produced warnings for auto-generated plan', {
        project_id: project.id,
        work_item_id: workItem?.id ?? null,
        warning_count: lintResult.warnings.length,
      });
      safeLogDecision({
        project_id: project.id,
        stage: LOOP_STATES.PLAN,
        action: 'plan_lint_warnings',
        reasoning: `plan lint produced ${lintResult.warnings.length} warning(s)`,
        inputs: {
          ...getWorkItemDecisionContext(workItem),
        },
        outcome: {
          warnings: lintResult.warnings,
        },
        confidence: 1,
        batch_id: batchId,
      });
    }

    if (descriptionQuality.blocked) {
      logger.warn('PLAN lint rejected auto-generated plan for vague task descriptions', {
        project_id: project.id,
        work_item_id: workItem?.id ?? null,
        failing_task_count: descriptionQuality.failures.length,
        threshold: descriptionQuality.threshold,
      });
      safeLogDecision({
        project_id: project.id,
        stage: LOOP_STATES.PLAN,
        action: 'plan_description_quality_rejected',
        reasoning: `plan description quality rejected ${descriptionQuality.failures.length} task(s) below threshold ${descriptionQuality.threshold}`,
        inputs: {
          ...getWorkItemDecisionContext(workItem),
        },
        outcome: {
          threshold: descriptionQuality.threshold,
          failures: descriptionQuality.failures.map((failure) => ({
            task_index: failure.task_index,
            task_title: failure.task_title,
            score: failure.score,
            threshold: failure.threshold,
            missing_signals: failure.missing_signals,
            reasons: failure.reasons,
          })),
        },
        confidence: 1,
        batch_id: batchId,
      });
      return {
        blocked: true,
        lintResult,
        descriptionQuality,
      };
    }

    return {
      blocked: false,
      lintResult,
      descriptionQuality,
    };
  }

  function isPathInside(parentPath, childPath) {
    if (!parentPath || !childPath) return false;
    const relative = path.relative(path.resolve(parentPath), path.resolve(childPath));
    return Boolean(relative) && !relative.startsWith('..') && !path.isAbsolute(relative);
  }

  function migrateGeneratedPlanPathForExecutionWorktree({
    project,
    workItem,
    executionWorkingDirectory,
  }) {
    const origin = getWorkItemOriginObject(workItem);
    const currentPlanPath = origin?.plan_path || null;
    if (
      !project
      || !workItem?.id
      || !currentPlanPath
      || !executionWorkingDirectory
      || executionWorkingDirectory === project.path
      || !isAutoGeneratedPlanPath(currentPlanPath)
      || isPathInside(executionWorkingDirectory, currentPlanPath)
    ) {
      return { workItem, planPath: currentPlanPath, migrated: false };
    }

    const targetPlanPath = buildAutoGeneratedPlanPath(project, workItem, executionWorkingDirectory);
    if (path.resolve(currentPlanPath) === path.resolve(targetPlanPath)) {
      return { workItem, planPath: currentPlanPath, migrated: false };
    }

    const sourceExists = fs.existsSync(currentPlanPath);
    const targetExists = fs.existsSync(targetPlanPath);
    if (!sourceExists && !targetExists) {
      return { workItem, planPath: currentPlanPath, migrated: false };
    }

    if (!targetExists && sourceExists) {
      fs.mkdirSync(path.dirname(targetPlanPath), { recursive: true });
      fs.copyFileSync(currentPlanPath, targetPlanPath);
    }

    const nextOrigin = {
      ...origin,
      plan_path: targetPlanPath,
    };
    const updatedWorkItem = factoryIntake.updateWorkItem(workItem.id, {
      origin_json: nextOrigin,
    }) || {
      ...workItem,
      origin: nextOrigin,
    };

    return {
      workItem: updatedWorkItem,
      planPath: targetPlanPath,
      migrated: true,
      previousPlanPath: currentPlanPath,
      targetPlanPath,
    };
  }

  function returnAutoGeneratedPlanToPrioritizeForDescriptionQuality({
    project,
    instance = null,
    workItem,
    lint,
    planPath,
    generator = PLAN_GENERATOR_LABEL,
    generationTaskId = null,
  }) {
    const rejectPayload = buildPlanDescriptionQualityRejectPayload(lint.descriptionQuality);
    const rejectReason = JSON.stringify(rejectPayload);
    const existingOrigin = getWorkItemOriginObject(workItem) || {};
    const priorCount = Number(existingOrigin.plan_description_quality_rejection_count || 0);
    const attemptCount = priorCount + 1;

    if (planPath && fs.existsSync(planPath)) {
      try {
        fs.unlinkSync(planPath);
      } catch (err) {
        logger.warn('PLAN lint could not remove rejected auto-generated plan file', {
          project_id: project.id,
          work_item_id: workItem?.id ?? null,
          plan_path: planPath,
          err: err.message,
        });
      }
    }

    // Phase X3: log the soft-threshold crossing for observability, but DO NOT
    // reject. The work item stays alive, gets routed to needs_replan with
    // updated rejection feedback, and PRIORITIZE will re-pick it (after the
    // Phase X1 cooldown) so the architect can try again — this time with the
    // Phase X2 PRIOR PLAN REJECTED block prepended to its prompt.
    if (attemptCount >= PLAN_QUALITY_SOFT_THRESHOLD) {
      logger.warn('PLAN: plan-quality soft threshold crossed — continuing via needs_replan', {
        project_id: project.id,
        work_item_id: workItem.id,
        attempt_count: attemptCount,
        soft_threshold: PLAN_QUALITY_SOFT_THRESHOLD,
      });

      safeLogDecision({
        project_id: project.id,
        stage: LOOP_STATES.PLAN,
        action: 'plan_quality_soft_threshold_crossed',
        reasoning: `Plan-quality gate has rejected ${attemptCount} architect-generated plans for this work item — past the soft threshold of ${PLAN_QUALITY_SOFT_THRESHOLD}. Per the plan-evolution model, the work item is NOT being rejected; it stays in needs_replan with feedback for the next architect attempt. A future strategy-escalation phase (Phase X5) will switch architect provider or decompose when same-shape failures persist.`,
        inputs: { ...getWorkItemDecisionContext(workItem) },
        outcome: {
          ...rejectPayload,
          work_item_id: workItem.id,
          attempt_count: attemptCount,
          soft_threshold: PLAN_QUALITY_SOFT_THRESHOLD,
          plan_path: planPath || null,
          generator,
          generation_task_id: generationTaskId,
        },
        confidence: 1,
        batch_id: getDecisionBatchId(project, workItem, null, instance),
      });
      // Fall through to the standard needs_replan path below — same code,
      // same persistence, just with the soft-threshold note logged above.
    }

    const origin = {
      ...existingOrigin,
      last_plan_description_quality_rejection: rejectPayload,
      plan_description_quality_rejection_count: attemptCount,
    };
    delete origin.plan_path;

    // Phase X3: needs_replan instead of prioritized. PRIORITIZE picks both
    // up (X1's WORK_ITEM_STATUS_ORDER), but needs_replan also triggers the
    // 5-min cooldown so the item doesn't immediately re-loop, AND signals
    // operator-visibly that this item has been through a rejection cycle
    // (vs a fresh prioritized item).
    const updatedWorkItem = factoryIntake.updateWorkItem(workItem.id, {
      status: 'needs_replan',
      reject_reason: rejectReason,
      origin_json: origin,
    });

    if (instance?.id) {
      rememberSelectedWorkItem(instance.id, updatedWorkItem);
    }

    safeLogDecision({
      project_id: project.id,
      stage: LOOP_STATES.PLAN,
      action: 'plan_description_quality_routed_to_needs_replan',
      reasoning: `Auto-generated plan task descriptions were below the deterministic specificity threshold; routing item to needs_replan with prior-rejection feedback (attempt ${attemptCount}, soft threshold ${PLAN_QUALITY_SOFT_THRESHOLD}). PRIORITIZE will re-pick after the Phase X1 cooldown and the architect will see the Phase X2 PRIOR PLAN REJECTED block.`,
      inputs: {
        ...getWorkItemDecisionContext(workItem),
      },
      outcome: {
        ...rejectPayload,
        work_item_id: updatedWorkItem.id,
        attempt_count: attemptCount,
        soft_threshold: PLAN_QUALITY_SOFT_THRESHOLD,
        next_state: LOOP_STATES.PRIORITIZE,
        next_status: 'needs_replan',
        plan_path: planPath || null,
        generator,
        generation_task_id: generationTaskId,
      },
      confidence: 1,
      batch_id: getDecisionBatchId(project, updatedWorkItem, null, instance),
    });

    return {
      reason: 'plan description quality rejected — routed to needs_replan',
      work_item: updatedWorkItem,
      stop_execution: true,
      next_state: LOOP_STATES.PRIORITIZE,
      stage_result: {
        status: 'needs_replan',
        reason: 'plan_description_quality_rejected',
        reject_reason: rejectReason,
        attempt_count: attemptCount,
        soft_threshold: PLAN_QUALITY_SOFT_THRESHOLD,
        description_quality: rejectPayload,
        plan_path: planPath || null,
        generator,
        generation_task_id: generationTaskId,
      },
    };
  }

  return {
    retireStalePendingPlanGenerationTask,
    getStoredPlanGeneratorProvider,
    getStoredPlanGenerationTaskId,
    getPlanGenerationWait,
    isPlanGenerationTaskPending,
    getPlanGenerationTask,
    persistPlanGenerationTaskReplacement,
    buildPlanGenerationDeferredResult,
    getPlanGenerationRetryCount,
    buildPlanGenerationProviderFallbackResult,
    buildPlanGenerationRetryResult,
    getPlanGeneratorLabel,
    findExistingPlanTaskSubmission,
    findActivePlanGenerationTask,
    findActiveProjectPlanGenerationTask,
    buildProjectPlanGenerationBusyResult,
    prepareAutoGeneratedPlanArtifactWorktree,
    extractPlanGenerationRawMarkdown,
    recoverTerminalPlanGenerationMarkdown,
    cleanupRecoveredSideWrittenPlan,
    normalizeAutoGeneratedPlanMarkdown,
    reviewAutoGeneratedPlan,
    lintAutoGeneratedPlan,
    migrateGeneratedPlanPathForExecutionWorktree,
    returnAutoGeneratedPlanToPrioritizeForDescriptionQuality,
  };
}

module.exports = { createPlanGenerationCluster, PLAN_GENERATOR_LABEL, WORK_ITEM_STATUS_ORDER };
